import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.time.LocalDate;
import java.util.*;
import java.util.HexFormat;
import java.util.regex.*;

/** S5.05 lab. Modes: luhn | scrub | cpf | inventory.  Detecting and masking personal data (LGPD) and card numbers (PCI DSS) in text such as logs.
 *  Card numbers used are the public TEST numbers of the payment industry; CPFs are generated by the check-digit algorithm (not real people). */
public class PiiLab {

    static boolean luhn(String digits) {
        int sum = 0; boolean dbl = false;
        for (int i = digits.length() - 1; i >= 0; i--) {
            int d = digits.charAt(i) - '0';
            if (dbl) { d *= 2; if (d > 9) d -= 9; }
            sum += d; dbl = !dbl;
        }
        return sum % 10 == 0;
    }
    /** a plausible card: 13-19 digits, Luhn ok, and a known issuer prefix (Visa 4, Mastercard 51-55/2221-2720, Amex 34/37). */
    static boolean plausiblePan(String d) {
        if (d.length() < 13 || d.length() > 19 || !luhn(d)) return false;
        int p2 = Integer.parseInt(d.substring(0, 2)), p4 = Integer.parseInt(d.substring(0, 4));
        return d.charAt(0) == '4' || (p2 >= 51 && p2 <= 55) || (p4 >= 2221 && p4 <= 2720) || p2 == 34 || p2 == 37;
    }

    static void luhnMode() {
        System.out.println("MODEL: how many RANDOM digit strings look like a card number? (seed 7, 1,000,000 strings per row)");
        Random r = new Random(7);
        int n = 1_000_000;
        for (int len : new int[]{16, 15, 12}) {
            int l = 0, p = 0;
            for (int i = 0; i < n; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < len; j++) sb.append((char) ('0' + r.nextInt(10)));
                String d = sb.toString();
                if (luhn(d)) l++;
                if (plausiblePan(d)) p++;
            }
            System.out.printf("  %2d digits: Luhn alone flags %6.2f%% | Luhn + issuer prefix + length 13-19 flags %5.2f%%%n", len, 100.0 * l / n, 100.0 * p / n);
        }
        System.out.println("\nPublic test numbers (the payment industry's own, not real cards):");
        for (String t : List.of("4111111111111111", "5555555555554444", "378282246310005", "4111111111111112"))
            System.out.println("  " + t + " luhn=" + luhn(t) + " plausible=" + plausiblePan(t));
        System.out.println("Reading: Luhn is a typo check (1 in 10 random strings pass). A scrubber that uses only Luhn will mangle order ids, phone numbers and timestamps;");
        System.out.println("prefix + length cut the noise but do not remove it; a long numeric id that happens to pass is still masked (cost of failing safe).");
    }

    // ---------------- scrub ----------------
    static final Pattern CAND = Pattern.compile("(?<![\\d])\\d(?:[ -]?\\d){12,18}(?![\\d])");

    static String maskPan(String digits) { return digits.substring(0, 6) + "*".repeat(digits.length() - 10) + digits.substring(digits.length() - 4); }

    static String scrub(String line, boolean strict) {
        Matcher m = CAND.matcher(line);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            String digits = m.group().replaceAll("[ -]", "");
            boolean hit = strict ? plausiblePan(digits) : luhn(digits);
            m.appendReplacement(out, Matcher.quoteReplacement(hit ? "[PAN " + digits.substring(digits.length() - 4) + "]" : m.group()));
        }
        m.appendTail(out);
        return out.toString();
    }

    static String luhnFix(String body) {      // appends the check digit that makes the string Luhn-valid
        for (char c = '0'; c <= '9'; c++) if (luhn(body + c)) return body + c;
        throw new IllegalStateException();
    }

    static void scrubMode() {
        System.out.println("MODEL: a log scrubber (regex candidate -> Luhn+prefix check -> replace with [PAN last4]). Test lines include formats a naive regex misses.\n");
        String orderPass = luhnFix("702611231234567");     // an order id that HAPPENS to pass Luhn (prefix 70: not a card brand)
        String orderPass4 = luhnFix("402611231234567");    // ... and one that also starts with 4
        record Line(String name, String text, boolean isCard) { }
        List<Line> cases = List.of(
            new Line("plain", "charge ok card=4111111111111111 amount=10.00", true),
            new Line("spaces", "card 4111 1111 1111 1111 declined", true),
            new Line("dashes", "card 4111-1111-1111-1111 declined", true),
            new Line("json", "{\"pan\":\"5555555555554444\",\"amount\":\"10.00\"}", true),
            new Line("amex 15", "amex 378282246310005 ok", true),
            new Line("order id (fails Luhn)", "order=2026112312345678 created", false),
            new Line("order id (passes Luhn, prefix 70)", "order=" + orderPass + " created", false),
            new Line("order id (passes Luhn, prefix 4)", "order=" + orderPass4 + " created", false),
            new Line("phone", "phone=+5511999990000 verified", false),
            new Line("split by a non-digit", "pan=41111111|11111111", true),
            new Line("url-encoded space", "card=4111%201111%201111%201111", true));
        int leaks = 0, fpStrict = 0, fpLuhn = 0;
        System.out.println(String.format("%-36s | %-46s | %s", "case", "strict scrubber output", "verdict"));
        for (Line c : cases) {
            String o = scrub(c.text(), true), o2 = scrub(c.text(), false);
            boolean masked = !o.equals(c.text()), maskedLuhn = !o2.equals(c.text());
            String v;
            if (c.isCard() && !masked) { v = "LEAK (card still readable)"; leaks++; }
            else if (!c.isCard() && masked) { v = "FALSE POSITIVE (masked a non-card)"; fpStrict++; }
            else v = "ok";
            if (!c.isCard() && maskedLuhn) fpLuhn++;
            System.out.println(String.format("%-36s | %-46s | %s", c.name(), o, v));
        }
        System.out.println("\nstrict (prefix + length + Luhn): leaks = " + leaks + ", false positives = " + fpStrict + " of " + cases.size() + " lines");
        System.out.println("Luhn only                      : false positives = " + fpLuhn + " (the order id with prefix 70 is masked too)");
        System.out.println("Reading: a scrubber is a SAFETY NET, not the control. The control is not logging the PAN at all (and not storing it): the net still leaks when the digits are split or encoded,");
        System.out.println("and it masks innocent numbers that happen to pass the check (the price of failing safe).");
        System.out.println("A PAN you MAY show keeps at most the first 6 and last 4 digits (rule to confirm in the PCI DSS text itself): maskPan(4111111111111111) = " + maskPan("4111111111111111"));
    }

    // ---------------- CPF ----------------
    static int cpfDigit(int[] d, int n) {
        int sum = 0;
        for (int i = 0; i < n; i++) sum += d[i] * (n + 1 - i);
        int r = (sum * 10) % 11;
        return r == 10 ? 0 : r;
    }
    static boolean cpfValid(String s) {
        String x = s.replaceAll("\\D", "");
        if (x.length() != 11 || x.chars().distinct().count() == 1) return false;
        int[] d = x.chars().map(c -> c - '0').toArray();
        return cpfDigit(d, 9) == d[9] && cpfDigit(d, 10) == d[10];
    }
    static String cpfFrom(int base9) {
        String b = String.format("%09d", base9);
        int[] d = new int[11];
        for (int i = 0; i < 9; i++) d[i] = b.charAt(i) - '0';
        d[9] = cpfDigit(d, 9); d[10] = cpfDigit(d, 10);
        StringBuilder sb = new StringBuilder();
        for (int v : d) sb.append(v);
        return sb.toString();
    }
    static String maskCpf(String cpf) { String x = cpf.replaceAll("\\D", ""); return "***." + x.substring(3, 6) + ".***-**"; }

    static void cpfMode() throws Exception {
        System.out.println("MODEL: CPF check digits (mod 11) and pseudonymization with HMAC. CPFs below are GENERATED from the algorithm for the exercise: no real person.\n");
        String ok = cpfFrom(123456780);
        System.out.println("generated CPF            : " + ok + "  valid=" + cpfValid(ok));
        String broken = ok.substring(0, 10) + (ok.charAt(10) == '0' ? '1' : '0');
        System.out.println("last digit changed       : " + broken + "  valid=" + cpfValid(broken));
        System.out.println("11111111111              : valid=" + cpfValid("11111111111") + "   (all-equal digits pass the formula but are rejected on purpose)");
        Random r = new Random(11); int n = 1_000_000, hit = 0;
        for (int i = 0; i < n; i++) { StringBuilder sb = new StringBuilder(); for (int j = 0; j < 11; j++) sb.append((char) ('0' + r.nextInt(10))); if (cpfValid(sb.toString())) hit++; }
        System.out.printf("random 11-digit strings that look like a valid CPF: %.2f%% (1 in ~100: a CPF detector in logs also needs context, e.g. the word 'cpf')%n", 100.0 * hit / n);
        System.out.println("masked for display       : " + maskCpf(ok));
        byte[] key = new byte[32]; new Random(5).nextBytes(key);
        Mac m = Mac.getInstance("HmacSHA256"); m.init(new SecretKeySpec(key, "HmacSHA256"));
        String tok1 = HexFormat.of().formatHex(m.doFinal(ok.getBytes()), 0, 8), tok2 = HexFormat.of().formatHex(m.doFinal(ok.getBytes()), 0, 8);
        System.out.println("pseudonym (HMAC, secret) : " + tok1 + "  same input -> same token: " + tok1.equals(tok2) + "  (analytics can join on it without seeing the CPF)");
        System.out.println("plain SHA-256 of a CPF   : brute-forceable: only ~10^9 possible bases x a published algorithm; the secret key is what makes the pseudonym safe.");
        java.security.MessageDigest sha = java.security.MessageDigest.getInstance("SHA-256");
        int N = 2_000_000; long t0 = System.nanoTime(); byte last = 0;
        for (int i = 0; i < N; i++) last ^= sha.digest(cpfFrom(i).getBytes())[0];
        double perSec = N / ((System.nanoTime() - t0) / 1e9);
        System.out.printf("measured here            : %.2f million (generate CPF + SHA-256)/s on ONE core -> all 10^9 bases in about %.0f min on one core (%.0f s on 12; extrapolation, ms vary)%n", perSec / 1e6, 1e9 / perSec / 60, 1e9 / perSec / 12);
    }

    // ---------------- inventory ----------------
    record Item(String table, String column, String category, String basis, Integer retentionDays, String lastPurge, String owner) { }

    static List<String> lint(List<Item> inv, String today) {
        List<String> p = new ArrayList<>();
        Set<String> bases = Set.of("contract", "legal-obligation", "legitimate-interest", "consent", "fraud-prevention");
        for (Item i : inv) {
            String k = i.table() + "." + i.column();
            if (i.basis() == null || !bases.contains(i.basis())) p.add(k + ": no valid legal basis");
            if (i.retentionDays() == null) p.add(k + ": no retention period");
            if (i.owner() == null || i.owner().isBlank()) p.add(k + ": no owner");
            if (i.retentionDays() != null && i.lastPurge() != null && !i.category().equals("financial-record")
                && java.time.temporal.ChronoUnit.DAYS.between(LocalDate.parse(i.lastPurge()), LocalDate.parse(today)) > 31)
                p.add(k + ": purge overdue (last purge " + i.lastPurge() + ", job should run monthly)");
        }
        return p;
    }

    static void inventoryMode() {
        System.out.println("MODEL: a data inventory (what personal data, why, how long, who owns it) with a linter. The rows are the PayFlow's PROPOSED columns; legal bases and retention are DRAFTS for legal review.\n");
        List<Item> good = List.of(
            new Item("users", "name", "identification", "contract", 1825, "2026-11-01", "identity-team"),
            new Item("users", "phone_e164", "contact", "contract", 1825, "2026-11-01", "identity-team"),
            new Item("users", "cpf", "identification", "legal-obligation", 1825, "2026-11-01", "identity-team"),
            new Item("ledger_entries", "amount", "financial-record", "legal-obligation", 1825, "2026-10-20", "payments-team"),
            new Item("access_logs", "ip_address", "technical", "legitimate-interest", 180, "2026-11-10", "platform-team"));
        List<Item> bad = List.of(
            new Item("users", "email", "contact", null, 1825, "2026-11-01", "identity-team"),
            new Item("heap_dumps", "any", "unknown", "legitimate-interest", null, null, ""),
            new Item("marketing_events", "device_id", "behaviour", "consent", 365, "2026-06-01", "growth-team"));
        List<String> a = lint(good, "2026-11-23"), b = lint(bad, "2026-11-23");
        System.out.println("proposed inventory (" + good.size() + " rows): " + (a.isEmpty() ? "0 problems" : a.size() + " problem(s)"));
        a.forEach(x -> System.out.println("  " + x));
        System.out.println("\nbroken inventory (" + bad.size() + " rows, written to FAIL): " + b.size() + " problem(s)");
        b.forEach(x -> System.out.println("  " + x));
        System.out.println("\nReading: the linter checks that the fields exist and the purge ran; it cannot say whether 'legitimate interest' is the right basis. That is a legal judgement (DPO/jurídico).");
    }

    public static void main(String[] a) throws Exception {
        switch (a.length > 0 ? a[0] : "luhn") { case "scrub" -> scrubMode(); case "cpf" -> cpfMode(); case "inventory" -> inventoryMode(); default -> luhnMode(); }
    }
}
